import { PersonColumnHeaders, PersonColumns } from '../../slots/defs/personRow';
import { usePeople } from '../people/people';
import type { Person } from '../people/people';
import { useRates } from '../rates/rates';
import { useFloorCents } from '../settings/settings';
import { useClaims, useLate } from '../claims/claims';
import { personPeriodDueCents, shownPersonDueTotal, usePeriods } from './periods';
import { Fig } from '../locale/Fig';

function PeriodHeaders({ sheet }: { sheet: string; user: string }) {
  const { data: periods = [] } = usePeriods(sheet);
  return (
    <>
      {periods.map((p) => (
        <th key={p.name}>{p.name} due</th>
      ))}
    </>
  );
}

// Per period on the sheet, the person's due-total for it: the due now of their claims whose due-by falls in it that counted at its end,
// fixed for everyone on the sheet when the period is closed (0.00 for a person added since). The period's own
// due-total is the sum of these.
function PersonPeriods({ sheet, person }: { sheet: string; user: string; person: Person }) {
  const { data: periods = [] } = usePeriods(sheet);
  const { data: claims = [] } = useClaims(sheet);
  const { data: people = [] } = usePeople(sheet);
  const { data: rates = [] } = useRates(sheet);
  const floor = useFloorCents(sheet);
  const late = useLate(sheet);

  const totals = personPeriodDueCents(periods, claims, people, rates, floor, late);

  return (
    <>
      {periods.map((p) => (
        <td key={p.name} data-testid={`person-period-${p.name}-due-total`}>
          <Fig>{shownPersonDueTotal(p, person.id, totals.get(p.name)?.get(person.id) ?? 0n)}</Fig>
        </td>
      ))}
    </>
  );
}

export const contributions = [
  PersonColumnHeaders.fill({ order: 15, Component: PeriodHeaders }),
  PersonColumns.fill({ order: 15, Component: PersonPeriods }),
];
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { claimDueCents, counted, countedOn } from '../claims/claims';
import type { Claim, Late } from '../claims/claims';
import { gradeOn } from '../people/people';
import type { Person } from '../people/people';
import { claimRateOf, twoDecimals } from '../rates/rates';
import type { Rate } from '../rates/rates';
import type { DatedCents } from '../settings/settings';

/** A period on the sheet: its name (unique on the sheet) and its from and to date (yyyy-MM-dd), inclusive;
 *  whether it is closed, its due-total fixed when closed (two decimals; null while open), and each person's due-total
 *  for it fixed then (by person id; empty while open, and a person added since has none); and whether it is
 *  soft-closed instead: its figures fixed the same way, while claims dated in it may still change; and the most OPEN or
 *  PENDING claims a person may have in it (null for no cap). */
export type Period = {
  name: string;
  from: string;
  to: string;
  closed: boolean;
  closedTotal: string | null;
  closedPeople: Record<string, string>;
  soft: boolean;
  cap: number | null;
};

export const periodsKey = (sheet: string) => ['periods', sheet] as const;

export const periodsPath = (sheet: string) => `/api/sheets/${encodeURIComponent(sheet)}/periods`;

/** Where monthly periods are generated between two dates. */
export const generatePeriodsPath = (sheet: string) => `${periodsPath(sheet)}/generate`;

/** Where a fiscal year's twelve monthly periods are generated. */
export const generateFiscalYearPath = (sheet: string) => `${periodsPath(sheet)}/generate-fy`;

/** The fiscal year a date (yyyy-MM-dd) falls in, named FY<yyyy> by the calendar year its first day falls in, for a
 *  fiscal year starting in the month (1 to 12). */
export function fiscalYearOf(date: string, startMonth: number): string {
  const year = Number(date.slice(0, 4));
  const month = Number(date.slice(5, 7));
  return `FY${month >= startMonth ? year : year - 1}`;
}

/** How many periods a generate made, with every period on the sheet after it. */
export type Generated = { made: number; periods: Period[] };

/** Where a period is closed. */
export const closePeriodPath = (sheet: string, name: string) =>
  `${periodsPath(sheet)}/${encodeURIComponent(name)}/close`;

/** Where a period is soft-closed. */
export const softClosePeriodPath = (sheet: string, name: string) =>
  `${periodsPath(sheet)}/${encodeURIComponent(name)}/soft-close`;

/** Where a closed or soft-closed period is reopened (a steward only). */
export const reopenPeriodPath = (sheet: string, name: string) =>
  `${periodsPath(sheet)}/${encodeURIComponent(name)}/reopen`;

/** Every period on the sheet, by from-date; no two overlap. */
export function usePeriods(sheet: string) {
  return useQuery({
    queryKey: periodsKey(sheet),
    queryFn: () => getJson<Period[]>(periodsPath(sheet)),
  });
}

/** The period whose dates contain the date (yyyy-MM-dd), or undefined when none does. */
export function periodOf(periods: Period[], date: string): Period | undefined {
  return periods.find((p) => p.from <= date && date <= p.to);
}

/** Each period's live due-total (in hundredths, by name): the due now of the claims whose due-by falls in it that counted
 *  at the end of its last day (see {@link countedOn}: OPEN, PENDING or SETTLED then by their status log, but not a
 *  deferred one, nor an unbound open one within its person's hold); a claim with no rate adds nothing. */
export function periodDueCents(
  periods: Period[],
  claims: Claim[],
  people: Person[],
  rates: Rate[],
  floor: DatedCents,
  late: Late,
): Map<string, bigint> {
  const totals = new Map<string, bigint>();
  for (const [name, byPerson] of personPeriodDueCents(periods, claims, people, rates, floor, late)) {
    totals.set(name, [...byPerson.values()].reduce((sum, due) => sum + due, 0n));
  }
  return totals;
}

/** Each period's live due-total per person (in hundredths, by period name then person id): the part of the period's
 *  due-total from the person's claims (see {@link periodDueCents}), so the people's add up to the period's. */
export function personPeriodDueCents(
  periods: Period[],
  claims: Claim[],
  people: Person[],
  rates: Rate[],
  floor: DatedCents,
  late: Late,
): Map<string, Map<number, bigint>> {
  const byId = new Map(people.map((p) => [p.id, p]));
  const totals = new Map<string, Map<number, bigint>>();
  for (const c of claims) {
    const period = periodOf(periods, c.dueBy);
    const person = byId.get(c.person);
    if (period === undefined || person === undefined || !countedOn(c, person, period.to)) continue;
    const due = claimDueCents(c, claimRateOf(rates, gradeOn(person, c.date), c), floor, late) ?? 0n;
    const byPerson = totals.get(period.name) ?? new Map<number, bigint>();
    byPerson.set(person.id, (byPerson.get(person.id) ?? 0n) + due);
    totals.set(period.name, byPerson);
  }
  return totals;
}

/** Each period's classic due-total (in hundredths, by name): the due now of the claims whose due-by falls in it that
 *  count by their status now (see {@link counted}: OPEN, PENDING or SETTLED), not by their status log; a claim with no
 *  rate adds nothing. */
export function classicPeriodDueCents(
  periods: Period[],
  claims: Claim[],
  people: Person[],
  rates: Rate[],
  floor: DatedCents,
  late: Late,
): Map<string, bigint> {
  const byId = new Map(people.map((p) => [p.id, p]));
  const totals = new Map<string, bigint>();
  for (const c of counted(claims, people)) {
    const period = periodOf(periods, c.dueBy);
    const person = byId.get(c.person);
    if (period === undefined || person === undefined) continue;
    const due = claimDueCents(c, claimRateOf(rates, gradeOn(person, c.date), c), floor, late) ?? 0n;
    totals.set(period.name, (totals.get(period.name) ?? 0n) + due);
  }
  return totals;
}

/** Whether a period's figures are fixed: closed or soft-closed. */
export function isFixed(period: Period): boolean {
  return period.closed || period.soft;
}

/** A person's due-total for a period as shown: the one fixed when it was (soft-)closed (0.00 for a person added since), else
 *  their live one. */
export function shownPersonDueTotal(period: Period, personId: number, liveCents: bigint): string {
  return isFixed(period) ? (period.closedPeople[String(personId)] ?? '0.00') : twoDecimals(liveCents);
}

/** A period's due-total as shown: the one fixed when it was (soft-)closed, else its live one. */
export function shownDueTotal(period: Period, liveCents: bigint): string {
  return isFixed(period) && period.closedTotal !== null ? period.closedTotal : twoDecimals(liveCents);
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimStatus;
import net.officefloor.hq.app.holiday.Holidays;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.setting.Dated;
import net.officefloor.hq.app.setting.Settings;

/**
 * A person on a sheet: name (unique on the sheet, ignoring case) and grades (A, B or C), each in force from its
 * from-date; grade is the one in force on the sheet's today. The version is raised by one on every save. The
 * retired-from date (yyyy-mm-dd) is null unless they are retired; once it is set they count as retired, whatever
 * the date. Their holds are listed in the order they were added; their OPEN claims dated within a hold, unless bound
 * by a statement, count in no live total. Their own terms (days) are null when they have none. retiredNow is whether
 * the sheet's today is on or after their retired-from date: from then their OPEN and PENDING claims, unless bound by a
 * statement, count in no live total. Their contact (trimmed, lower-cased, not another's on the sheet) is null when they
 * have none. clashing is whether their name or one of their aliases is already a name or alias on another sheet of
 * the sheet's tree (its ancestors and descendants): every edit of them is refused until it renames them out of it.
 * Their origin is the sheet they were transferred from, null for anyone not transferred. Their retirements are the
 * past ones (each ended by unretiring them), in the order they were unretired. Their tags are lower-cased, repeats
 * dropped, sorted: a claim of theirs counts in the due-total of each.
 */
public record Person(long id, String name, String grade, long version, String retiredFrom, List<Hold> holds,
        List<GradeFrom> grades, Integer terms, boolean retiredNow, String contact, boolean clashing, String origin,
        List<Retirement> retirements, List<String> tags) {

    /**
     * Whether the claim, theirs, counts toward the live totals: it counts, unless it is open, not bound by a statement,
     * and dated within one of their holds or their retirement date is reached.
     */
    public boolean counts(Claim claim) {
        if (!claim.counts()) {
            return false;
        }
        if (claim.status() == ClaimStatus.SETTLED || claim.bound()) {
            return true;
        }
        return !retiredNow && holds.stream().noneMatch((h) -> h.covers(claim.date()));
    }

    /** This person as they stand with the date for the sheet's today: their grade in force then, and retired then or not. */
    public Person on(LocalDate today) {
        return new Person(id, name, gradeOn(grades, today), version, retiredFrom, holds, grades, terms,
                retiredOn(retiredFrom, today), contact, clashing, origin, retirements, tags);
    }

    /** Whether the sheet's today is on or after the retired-from date (null: never retired). */
    static boolean retiredOn(String retiredFrom, LocalDate today) {
        return retiredFrom != null && !today.isBefore(LocalDate.parse(retiredFrom));
    }

    /**
     * Whether the claim, theirs, counts toward a period ending on the date: by the status it had at the end of that
     * day (OPEN, PENDING or SETTLED; not yet added: no), unless deferred now, or open now, not bound by a statement
     * and dated within one of their holds or their retirement date is reached.
     */
    public boolean countsOn(Claim claim, LocalDate end) {
        ClaimStatus then = claim.statusOn(end);
        if (claim.deferred() || then == null) {
            return false;
        }
        if (then == ClaimStatus.SETTLED) {
            return true;
        }
        if (then != ClaimStatus.OPEN && then != ClaimStatus.PENDING) {
            return false;
        }
        return (claim.status() != ClaimStatus.OPEN && claim.status() != ClaimStatus.PENDING) || claim.bound()
                || (!retiredNow && holds.stream().noneMatch((h) -> h.covers(claim.date())));
    }

    /**
     * Whether a claim dated {@code date} is after this person's retirement, or after the from and before the to of a
     * past one, and so refused.
     */
    public boolean retiredBefore(LocalDate date) {
        return (retiredFrom != null && date.isAfter(LocalDate.parse(retiredFrom)))
                || retirements.stream().anyMatch((r) -> r.within(date.toString()));
    }

    /** The grade in force on the date: the one whose from-date is the latest on or before it (null when none). */
    public String gradeOn(LocalDate date) {
        return gradeOn(grades, date);
    }

    /**
     * Whether the claim has a figure apart from the grade in force on {@code today}: one it keeps (settled or
     * bound), one at another grade, in force on its date, or one from a rate that ended (its to-date) on or before
     * today, the claim not being dated after today. Their due-total is n/a only when no claim does and that grade
     * has no rate on today.
     */
    public boolean figureApartFrom(Claim claim, LocalDate today, List<Rate> rates, Dated floor) {
        String then = gradeOn(claim.date());
        return claim.fixed()
                || (then != null && !then.equals(gradeOn(today)) && claim.figure(rates, then, floor) != null)
                || (then != null && !LocalDate.parse(claim.date()).isAfter(today)
                        && claim.figure(rates, then, floor) != null);
    }

    /**
     * The due-by of a claim of theirs dated {@code date}, fixed when it is made: the terms-th business day after the
     * date (skipping weekends and the sheet's holidays as they stand now), the terms being the first of their own
     * terms, the terms of their grade then, and the sheet's terms then.
     */
    public LocalDate dueBy(String sheet, LocalDate date, Settings settings, Holidays holidays) {
        return holidays.businessDaysAfter(sheet, date, termsOn(sheet, date, settings));
    }

    /** The terms a claim of theirs dated {@code date} is fixed with: their own, else their grade's then, else the sheet's then. */
    public int termsOn(String sheet, LocalDate date, Settings settings) {
        return terms != null ? terms : settings.terms(sheet, gradeOn(date), date);
    }

    /** The grade in force on the claim's date (yyyy-mm-dd). */
    public String gradeOn(String date) {
        return gradeOn(LocalDate.parse(date));
    }

    static String gradeOn(List<GradeFrom> grades, LocalDate date) {
        GradeFrom found = null;
        for (GradeFrom g : grades) {
            if (g.from() != null && LocalDate.parse(g.from()).isAfter(date)) {
                continue;
            }
            if (found == null || (found.from() != null && g.from() != null && g.from().compareTo(found.from()) > 0)
                    || (found.from() == null && g.from() != null)) {
                found = g;
            }
        }
        return found == null ? null : found.grade();
    }
}
